  /* ---------------- doubly linked lists ---------------- */
  const DL_H = "typedef struct dlistint_s\n{\n\tint n;\n\tstruct dlistint_s *prev;\n\tstruct dlistint_s *next;\n} dlistint_t;\nsize_t print_dlistint(const dlistint_t *h);\ndlistint_t *add_dnodeint(dlistint_t **head, const int n);\ndlistint_t *add_dnodeint_end(dlistint_t **head, const int n);\nvoid free_dlistint(dlistint_t *head);\nint delete_dnodeint_at_index(dlistint_t **head, unsigned int index);\n";
  const DL_SOL = "#include <stdio.h>\n#include <stdlib.h>\n#include \"lists.h\"\n\n/**\n * print_dlistint - prints a list\n * @h: head\n *\n * Return: number of nodes\n */\nsize_t print_dlistint(const dlistint_t *h)\n{\n\tsize_t c = 0;\n\n\tfor (; h; h = h->next, c++)\n\t\tprintf(\"%d\\n\", h->n);\n\treturn (c);\n}\n\n/**\n * add_dnodeint - adds at the beginning\n * @head: list\n * @n: value\n *\n * Return: new node or NULL\n */\ndlistint_t *add_dnodeint(dlistint_t **head, const int n)\n{\n\tdlistint_t *node = malloc(sizeof(*node));\n\n\tif (node == NULL)\n\t\treturn (NULL);\n\tnode->n = n;\n\tnode->prev = NULL;\n\tnode->next = *head;\n\tif (*head)\n\t\t(*head)->prev = node;\n\t*head = node;\n\treturn (node);\n}\n\n/**\n * add_dnodeint_end - adds at the end\n * @head: list\n * @n: value\n *\n * Return: new node or NULL\n */\ndlistint_t *add_dnodeint_end(dlistint_t **head, const int n)\n{\n\tdlistint_t *node = malloc(sizeof(*node)), *t;\n\n\tif (node == NULL)\n\t\treturn (NULL);\n\tnode->n = n;\n\tnode->next = NULL;\n\tnode->prev = NULL;\n\tif (*head == NULL)\n\t{\n\t\t*head = node;\n\t\treturn (node);\n\t}\n\tfor (t = *head; t->next; t = t->next)\n\t\t;\n\tt->next = node;\n\tnode->prev = t;\n\treturn (node);\n}\n\n/**\n * free_dlistint - frees a list\n * @head: list\n */\nvoid free_dlistint(dlistint_t *head)\n{\n\tdlistint_t *next;\n\n\tfor (; head; head = next)\n\t{\n\t\tnext = head->next;\n\t\tfree(head);\n\t}\n}\n\n/**\n * delete_dnodeint_at_index - deletes a node\n * @head: list\n * @index: position\n *\n * Return: 1 or -1\n */\nint delete_dnodeint_at_index(dlistint_t **head, unsigned int index)\n{\n\tdlistint_t *t = *head;\n\n\tfor (; t && index; index--)\n\t\tt = t->next;\n\tif (t == NULL)\n\t\treturn (-1);\n\tif (t->prev)\n\t\tt->prev->next = t->next;\n\telse\n\t\t*head = t->next;\n\tif (t->next)\n\t\tt->next->prev = t->prev;\n\tfree(t);\n\treturn (1);\n}\n";
