  /* ---------------- monty (stacks & queues) ---------------- */
  const MONTY_SOL = "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\n/**\n * is_int - checks an integer string\n * @s: string\n *\n * Return: 1 if integer\n */\nint is_int(const char *s)\n{\n\tif (s == NULL || *s == '\\0')\n\t\treturn (0);\n\tif (*s == '-' || *s == '+')\n\t\ts++;\n\tif (*s == '\\0')\n\t\treturn (0);\n\tfor (; *s; s++)\n\t\tif (!isdigit((unsigned char)*s))\n\t\t\treturn (0);\n\treturn (1);\n}\n\n/**\n * main - a tiny Monty interpreter reading bytecodes from stdin\n *\n * Return: EXIT_SUCCESS or EXIT_FAILURE\n */\nint main(void)\n{\n\tchar line[1024], *op, *arg;\n\tint stack[1024], top = 0, t;\n\tunsigned int ln = 0;\n\n\twhile (fgets(line, sizeof(line), stdin))\n\t{\n\t\tln++;\n\t\top = strtok(line, \" \\t\\n\");\n\t\tif (op == NULL || op[0] == '#' || strcmp(op, \"nop\") == 0)\n\t\t\tcontinue;\n\t\tif (strcmp(op, \"push\") == 0)\n\t\t{\n\t\t\targ = strtok(NULL, \" \\t\\n\");\n\t\t\tif (!is_int(arg))\n\t\t\t{\n\t\t\t\tfprintf(stderr, \"L%u: usage: push integer\\n\", ln);\n\t\t\t\treturn (EXIT_FAILURE);\n\t\t\t}\n\t\t\tstack[top++] = atoi(arg);\n\t\t}\n\t\telse if (strcmp(op, \"pall\") == 0)\n\t\t{\n\t\t\tfor (t = top - 1; t >= 0; t--)\n\t\t\t\tprintf(\"%d\\n\", stack[t]);\n\t\t}\n\t\telse if (strcmp(op, \"pint\") == 0)\n\t\t{\n\t\t\tif (top == 0)\n\t\t\t{\n\t\t\t\tfprintf(stderr, \"L%u: can't pint, stack empty\\n\", ln);\n\t\t\t\treturn (EXIT_FAILURE);\n\t\t\t}\n\t\t\tprintf(\"%d\\n\", stack[top - 1]);\n\t\t}\n\t\telse if (strcmp(op, \"pop\") == 0)\n\t\t{\n\t\t\tif (top == 0)\n\t\t\t{\n\t\t\t\tfprintf(stderr, \"L%u: can't pop an empty stack\\n\", ln);\n\t\t\t\treturn (EXIT_FAILURE);\n\t\t\t}\n\t\t\ttop--;\n\t\t}\n\t\telse if (strcmp(op, \"swap\") == 0 || strcmp(op, \"add\") == 0)\n\t\t{\n\t\t\tif (top < 2)\n\t\t\t{\n\t\t\t\tfprintf(stderr, \"L%u: can't %s, stack too short\\n\", ln, op);\n\t\t\t\treturn (EXIT_FAILURE);\n\t\t\t}\n\t\t\tif (op[0] == 's')\n\t\t\t{\n\t\t\t\tt = stack[top - 1];\n\t\t\t\tstack[top - 1] = stack[top - 2];\n\t\t\t\tstack[top - 2] = t;\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tstack[top - 2] += stack[top - 1];\n\t\t\t\ttop--;\n\t\t\t}\n\t\t}\n\t\telse\n\t\t{\n\t\t\tfprintf(stderr, \"L%u: unknown instruction %s\\n\", ln, op);\n\t\t\treturn (EXIT_FAILURE);\n\t\t}\n\t}\n\treturn (EXIT_SUCCESS);\n}\n";
