  /* ---------------- hash tables ---------------- */
  const HT_H = "typedef struct hash_node_s\n{\n\tchar *key;\n\tchar *value;\n\tstruct hash_node_s *next;\n} hash_node_t;\ntypedef struct hash_table_s\n{\n\tunsigned long int size;\n\thash_node_t **array;\n} hash_table_t;\nhash_table_t *hash_table_create(unsigned long int size);\nunsigned long int hash_djb2(const unsigned char *str);\nunsigned long int key_index(const unsigned char *key, unsigned long int size);\nint hash_table_set(hash_table_t *ht, const char *key, const char *value);\nchar *hash_table_get(const hash_table_t *ht, const char *key);\nvoid hash_table_print(const hash_table_t *ht);\nvoid hash_table_delete(hash_table_t *ht);\n";
  const HT_SOL = "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include \"hash_tables.h\"\n\n/**\n * hash_table_create - creates a hash table\n * @size: array size\n *\n * Return: table or NULL\n */\nhash_table_t *hash_table_create(unsigned long int size)\n{\n\thash_table_t *ht = malloc(sizeof(*ht));\n\n\tif (ht == NULL)\n\t\treturn (NULL);\n\tht->size = size;\n\tht->array = calloc(size, sizeof(hash_node_t *));\n\tif (ht->array == NULL)\n\t{\n\t\tfree(ht);\n\t\treturn (NULL);\n\t}\n\treturn (ht);\n}\n\n/**\n * hash_djb2 - djb2 hash\n * @str: string\n *\n * Return: hash\n */\nunsigned long int hash_djb2(const unsigned char *str)\n{\n\tunsigned long int hash = 5381;\n\tint c;\n\n\twhile ((c = *str++))\n\t\thash = ((hash << 5) + hash) + c;\n\treturn (hash);\n}\n\n/**\n * key_index - index of a key\n * @key: key\n * @size: table size\n *\n * Return: index\n */\nunsigned long int key_index(const unsigned char *key, unsigned long int size)\n{\n\treturn (hash_djb2(key) % size);\n}\n\n/**\n * hash_table_set - adds or updates a key\n * @ht: table\n * @key: key\n * @value: value\n *\n * Return: 1 or 0\n */\nint hash_table_set(hash_table_t *ht, const char *key, const char *value)\n{\n\tunsigned long int i;\n\thash_node_t *n;\n\tchar *v;\n\n\tif (ht == NULL || key == NULL || *key == '\\0' || value == NULL)\n\t\treturn (0);\n\ti = key_index((const unsigned char *)key, ht->size);\n\tfor (n = ht->array[i]; n; n = n->next)\n\t\tif (strcmp(n->key, key) == 0)\n\t\t{\n\t\t\tv = strdup(value);\n\t\t\tif (v == NULL)\n\t\t\t\treturn (0);\n\t\t\tfree(n->value);\n\t\t\tn->value = v;\n\t\t\treturn (1);\n\t\t}\n\tn = malloc(sizeof(*n));\n\tif (n == NULL)\n\t\treturn (0);\n\tn->key = strdup(key);\n\tn->value = strdup(value);\n\tn->next = ht->array[i];\n\tht->array[i] = n;\n\treturn (1);\n}\n\n/**\n * hash_table_get - gets a value\n * @ht: table\n * @key: key\n *\n * Return: value or NULL\n */\nchar *hash_table_get(const hash_table_t *ht, const char *key)\n{\n\thash_node_t *n;\n\n\tif (ht == NULL || key == NULL || *key == '\\0')\n\t\treturn (NULL);\n\tfor (n = ht->array[key_index((const unsigned char *)key, ht->size)]; n; n = n->next)\n\t\tif (strcmp(n->key, key) == 0)\n\t\t\treturn (n->value);\n\treturn (NULL);\n}\n\n/**\n * hash_table_print - prints a hash table\n * @ht: table\n */\nvoid hash_table_print(const hash_table_t *ht)\n{\n\tunsigned long int i;\n\thash_node_t *n;\n\tchar *sep = \"\";\n\n\tif (ht == NULL)\n\t\treturn;\n\tprintf(\"{\");\n\tfor (i = 0; i < ht->size; i++)\n\t\tfor (n = ht->array[i]; n; n = n->next)\n\t\t{\n\t\t\tprintf(\"%s'%s': '%s'\", sep, n->key, n->value);\n\t\t\tsep = \", \";\n\t\t}\n\tprintf(\"}\\n\");\n}\n\n/**\n * hash_table_delete - frees a table\n * @ht: table\n */\nvoid hash_table_delete(hash_table_t *ht)\n{\n\tunsigned long int i;\n\thash_node_t *n, *next;\n\n\tif (ht == NULL)\n\t\treturn;\n\tfor (i = 0; i < ht->size; i++)\n\t\tfor (n = ht->array[i]; n; n = next)\n\t\t{\n\t\t\tnext = n->next;\n\t\t\tfree(n->key);\n\t\t\tfree(n->value);\n\t\t\tfree(n);\n\t\t}\n\tfree(ht->array);\n\tfree(ht);\n}\n";
