  /* ---------------- binary trees ---------------- */
  const BT_H = "typedef struct binary_tree_s\n{\n\tint n;\n\tstruct binary_tree_s *parent;\n\tstruct binary_tree_s *left;\n\tstruct binary_tree_s *right;\n} binary_tree_t;\nbinary_tree_t *binary_tree_node(binary_tree_t *parent, int value);\nsize_t binary_tree_height(const binary_tree_t *tree);\nsize_t binary_tree_size(const binary_tree_t *tree);\nvoid binary_tree_preorder(const binary_tree_t *tree, void (*func)(int));\nvoid binary_tree_inorder(const binary_tree_t *tree, void (*func)(int));\nint binary_tree_is_bst(const binary_tree_t *tree);\nbinary_tree_t *bst_insert(binary_tree_t **tree, int value);\n";
  const BT_NODE = "/**\n * binary_tree_node - creates a node\n * @parent: parent\n * @value: value\n *\n * Return: node or NULL\n */\nbinary_tree_t *binary_tree_node(binary_tree_t *parent, int value)\n{\n\tbinary_tree_t *n = malloc(sizeof(*n));\n\n\tif (n == NULL)\n\t\treturn (NULL);\n\tn->n = value;\n\tn->parent = parent;\n\tn->left = NULL;\n\tn->right = NULL;\n\treturn (n);\n}\n";
  const BT_SOL = "#include <stdlib.h>\n#include <limits.h>\n#include \"binary_trees.h\"\n\n" + BT_NODE + "\n/**\n * binary_tree_height - height of a tree (edges)\n * @tree: tree\n *\n * Return: height, 0 if NULL\n */\nsize_t binary_tree_height(const binary_tree_t *tree)\n{\n\tsize_t l, r;\n\n\tif (tree == NULL || (tree->left == NULL && tree->right == NULL))\n\t\treturn (0);\n\tl = tree->left ? 1 + binary_tree_height(tree->left) : 0;\n\tr = tree->right ? 1 + binary_tree_height(tree->right) : 0;\n\treturn (l > r ? l : r);\n}\n\n/**\n * binary_tree_size - number of nodes\n * @tree: tree\n *\n * Return: size\n */\nsize_t binary_tree_size(const binary_tree_t *tree)\n{\n\tif (tree == NULL)\n\t\treturn (0);\n\treturn (1 + binary_tree_size(tree->left) + binary_tree_size(tree->right));\n}\n\n/**\n * binary_tree_preorder - pre-order traversal\n * @tree: tree\n * @func: callback\n */\nvoid binary_tree_preorder(const binary_tree_t *tree, void (*func)(int))\n{\n\tif (tree == NULL || func == NULL)\n\t\treturn;\n\tfunc(tree->n);\n\tbinary_tree_preorder(tree->left, func);\n\tbinary_tree_preorder(tree->right, func);\n}\n\n/**\n * binary_tree_inorder - in-order traversal\n * @tree: tree\n * @func: callback\n */\nvoid binary_tree_inorder(const binary_tree_t *tree, void (*func)(int))\n{\n\tif (tree == NULL || func == NULL)\n\t\treturn;\n\tbinary_tree_inorder(tree->left, func);\n\tfunc(tree->n);\n\tbinary_tree_inorder(tree->right, func);\n}\n\n/**\n * is_bst - helper with bounds\n * @t: tree\n * @lo: lower bound (exclusive)\n * @hi: upper bound (exclusive)\n *\n * Return: 1 or 0\n */\nint is_bst(const binary_tree_t *t, long lo, long hi)\n{\n\tif (t == NULL)\n\t\treturn (1);\n\tif (t->n <= lo || t->n >= hi)\n\t\treturn (0);\n\treturn (is_bst(t->left, lo, t->n) && is_bst(t->right, t->n, hi));\n}\n\n/**\n * binary_tree_is_bst - checks a BST\n * @tree: tree\n *\n * Return: 1 or 0\n */\nint binary_tree_is_bst(const binary_tree_t *tree)\n{\n\tif (tree == NULL)\n\t\treturn (0);\n\treturn (is_bst(tree, (long)INT_MIN - 1, (long)INT_MAX + 1));\n}\n\n/**\n * bst_insert - inserts in a BST (ignores duplicates)\n * @tree: root pointer\n * @value: value\n *\n * Return: new node or NULL\n */\nbinary_tree_t *bst_insert(binary_tree_t **tree, int value)\n{\n\tbinary_tree_t *cur, *parent = NULL;\n\n\tif (tree == NULL)\n\t\treturn (NULL);\n\tfor (cur = *tree; cur; )\n\t{\n\t\tif (value == cur->n)\n\t\t\treturn (NULL);\n\t\tparent = cur;\n\t\tcur = value < cur->n ? cur->left : cur->right;\n\t}\n\tcur = binary_tree_node(parent, value);\n\tif (cur == NULL)\n\t\treturn (NULL);\n\tif (parent == NULL)\n\t\t*tree = cur;\n\telse if (value < parent->n)\n\t\tparent->left = cur;\n\telse\n\t\tparent->right = cur;\n\treturn (cur);\n}\n";
